// path: [{x,y}, ...]; e: {x,y,speed,wp:0,done:false}
function followPath(e, path, dt) {
  if (e.done || e.wp >= path.length) { e.done = true; return; }
  const t = path[e.wp];
  const dx = t.x - e.x, dy = t.y - e.y, d = Math.hypot(dx, dy);
  const step = e.speed * dt;
  if (d <= step) { e.x = t.x; e.y = t.y; e.wp++; }   // reached this node
  else { e.x += dx / d * step; e.y += dy / d * step; }
}
// Spawn movers with e.wp=0; when e.done they reached the end (leak/goal).
```

